import{_ as a,o as d,c as r,a as e}from"./chunks/framework.Ld7uezS_.js";const p=JSON.parse('{"title":"1. 职业道德","description":"","frontmatter":{},"headers":[],"relativePath":"theory/01-professional-ethics.md","filePath":"theory/01-professional-ethics.md","lastUpdated":1787281221000}'),o={name:"theory/01-professional-ethics.md"};function l(i,t,h,s,n,c){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="_1-职业道德" tabindex="-1">1. 职业道德 <a class="header-anchor" href="#_1-职业道德" aria-label="Permalink to &quot;1. 职业道德&quot;">​</a></h1><h2 id="本章学习目标" tabindex="-1">本章学习目标 <a class="header-anchor" href="#本章学习目标" aria-label="Permalink to &quot;本章学习目标&quot;">​</a></h2><p>学完本章，你应该能解释“职业道德”与“消防法规”的区别，背出四条职业守则，并能把每条守则应用到消防控制室值班和现场操作中。</p><h2 id="一、先理解-为什么操作员必须讲职业道德" tabindex="-1">一、先理解：为什么操作员必须讲职业道德 <a class="header-anchor" href="#一、先理解-为什么操作员必须讲职业道德" aria-label="Permalink to &quot;一、先理解：为什么操作员必须讲职业道德&quot;">​</a></h2><p>消防设施操作员不是普通设备管理员。你看到的一个故障、屏蔽或火灾报警，可能意味着建筑正在失去保护。如果为了让声音停止而复位、为了省事而长期屏蔽、为了赶进度而跳过安全确认，后果可能影响人员疏散和消防救援。</p><p>所以职业道德不是抽象口号，而是岗位决策顺序：<strong>先保护人员，再按规程判断；先如实记录，再报告升级；不确定时停止冒险操作。</strong></p><h2 id="二、职业道德基本知识" tabindex="-1">二、职业道德基本知识 <a class="header-anchor" href="#二、职业道德基本知识" aria-label="Permalink to &quot;二、职业道德基本知识&quot;">​</a></h2><ul><li><strong>职业道德</strong>：从事一定职业的人在职业活动中应遵循的行为准则。</li><li><strong>消防职业道德</strong>：消防设施操作员在监控、操作、保养、维修、检测等工作中，为正确处理岗位关系而遵守的行为规范。</li><li>它与法律法规不同：法律法规由国家强制实施，职业道德更多体现岗位责任和行为要求；两者在消防岗位上共同约束不安全行为。</li></ul><h2 id="三、职业道德、法律、制度和授权不是一回事" tabindex="-1">三、职业道德、法律、制度和授权不是一回事 <a class="header-anchor" href="#三、职业道德、法律、制度和授权不是一回事" aria-label="Permalink to &quot;三、职业道德、法律、制度和授权不是一回事&quot;">​</a></h2><p>零基础学习时，可以用“来源—约束—后果—岗位动作”四个问题区分：</p><table tabindex="0"><thead><tr><th>概念</th><th>从哪里来</th><th>主要约束什么</th><th>违反后的典型后果</th><th>岗位例子</th></tr></thead><tbody><tr><td>法律法规</td><td>国家立法和行政管理文件</td><td>必须履行的法定义务</td><td>可能承担行政、民事或刑事责任</td><td>不得占用疏散通道，发现火灾应报警</td></tr><tr><td>单位制度</td><td>本单位管理制度和预案</td><td>本单位的流程、审批和报告</td><td>可能造成管理责任、考核或事故后果</td><td>屏蔽设备要审批、登记和告知</td></tr><tr><td>操作规程</td><td>岗位或设备的具体作业文件</td><td>某项操作怎样安全执行</td><td>可能导致误操作、设备损坏或人身伤害</td><td>按设备说明书确认手动/自动状态</td></tr><tr><td>岗位授权</td><td>组织赋予某人的权限范围</td><td>谁可以操作、维修、停用或批准</td><td>越权操作导致责任不清和风险扩大</td><td>值班员不能擅自修改联动逻辑</td></tr><tr><td>职业道德</td><td>职业共同认可的行为准则</td><td>是否如实、负责、守规、复核</td><td>失信、失职，可能进一步引发纪律或法律后果</td><td>不瞒报、不乱改、不漏记</td></tr></tbody></table><p>遇到现场异常时，先判断“我是否有权做这件事”，再判断“这件事是否有规程和安全条件”。有权不代表可以省略规程；没有权限也不能因为别人催促就擅自操作。</p><h3 id="岗位判断例子" tabindex="-1">岗位判断例子 <a class="header-anchor" href="#岗位判断例子" aria-label="Permalink to &quot;岗位判断例子&quot;">​</a></h3><ul><li><strong>失职</strong>：看见长期故障却不记录、不报告；</li><li><strong>越权</strong>：未经批准修改联动逻辑或长期停用设施；</li><li><strong>误操作</strong>：有操作权限，但没有确认对象、状态和影响就按错按钮；</li><li><strong>合规处置</strong>：记录事实、报告影响、落实临时措施，由授权人员处理并复核恢复。</li></ul><h2 id="三、四条职业守则与岗位例子" tabindex="-1">三、四条职业守则与岗位例子 <a class="header-anchor" href="#三、四条职业守则与岗位例子" aria-label="Permalink to &quot;三、四条职业守则与岗位例子&quot;">​</a></h2><table tabindex="0"><thead><tr><th>守则</th><th>用大白话理解</th><th>工作中的例子</th></tr></thead><tbody><tr><td>以人为本，生命至上</td><td>任何设备操作都不能把人员安全放在后面</td><td>现场确认有人员被困时，先报告、疏散和救援，不先追求“消掉报警”</td></tr><tr><td>忠于职守，严守规程</td><td>按值班制度、操作规程和授权范围工作</td><td>交接班如实说明屏蔽、故障和未完成事项</td></tr><tr><td>钻研业务，精益求精</td><td>不只背按钮位置，还要理解系统为什么这样动作</td><td>练习时同时观察控制器显示、现场动作和反馈信号</td></tr><tr><td>临危不乱，科学处置</td><td>遇到报警不慌乱、不猜测、不盲目操作</td><td>先确认报警类别和地址，再按预案核实、报告和处置</td></tr></tbody></table><h2 id="四、把方针和原则分开记" tabindex="-1">四、把方针和原则分开记 <a class="header-anchor" href="#四、把方针和原则分开记" aria-label="Permalink to &quot;四、把方针和原则分开记&quot;">​</a></h2><ul><li><strong>消防工作方针</strong>：预防为主，防消结合。它回答“消防工作的总方向是什么”。</li><li><strong>消防工作原则</strong>：政府统一领导、部门依法监管、单位全面负责、公民积极参与。它回答“不同主体分别承担什么责任”。</li></ul><h2 id="五、场景练习" tabindex="-1">五、场景练习 <a class="header-anchor" href="#五、场景练习" aria-label="Permalink to &quot;五、场景练习&quot;">​</a></h2><p><strong>场景</strong>：控制器显示某房间火灾报警，现场暂时没有看到明火。</p><p>错误做法：认为“没有看到明火就是误报”，直接复位。</p><p>正确思路：记录地址和时间 → 通过现场核实或通信方式确认 → 按预案报告和组织处置 → 只有在确认条件满足后按程序复位，并确认系统恢复。</p><h2 id="六、把职业道德拆成可执行动作" tabindex="-1">六、把职业道德拆成可执行动作 <a class="header-anchor" href="#六、把职业道德拆成可执行动作" aria-label="Permalink to &quot;六、把职业道德拆成可执行动作&quot;">​</a></h2><p>考试和工作中，可以把职业道德落实为四个动作：</p><ol><li><strong>如实</strong>：不隐瞒火警、故障、屏蔽、停用和未完成事项；</li><li><strong>守规</strong>：按授权、制度、设备说明书和检测方案操作；</li><li><strong>负责</strong>：发现影响保护功能的异常，及时报告并跟踪恢复；</li><li><strong>复核</strong>：操作、维修或检测后，确认反馈、状态和记录一致。</li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>记忆句：<strong>不瞒报、不越权、不乱改、不漏记。</strong> 这四句话不是新的法规条文，而是帮助理解职业守则的学习口诀。</p></div><h2 id="七、典型违规后果" tabindex="-1">七、典型违规后果 <a class="header-anchor" href="#七、典型违规后果" aria-label="Permalink to &quot;七、典型违规后果&quot;">​</a></h2><table tabindex="0"><thead><tr><th>行为</th><th>直接问题</th><th>正确替代</th></tr></thead><tbody><tr><td>为了安静直接消音后复位</td><td>可能掩盖真实火警或故障</td><td>先记录、核实、报告，再按条件复位</td></tr><tr><td>长期屏蔽设备不登记</td><td>形成保护盲区且无法追溯</td><td>说明影响范围、落实临时措施并限期修复</td></tr><tr><td>未授权改变联动逻辑</td><td>可能造成误动作或拒动作</td><td>由授权人员按设计文件和变更流程处理</td></tr><tr><td>只口头交接异常</td><td>下一班无法准确判断状态</td><td>使用值班记录并由交接双方确认</td></tr></tbody></table><h2 id="八、自测" tabindex="-1">八、自测 <a class="header-anchor" href="#八、自测" aria-label="Permalink to &quot;八、自测&quot;">​</a></h2><ol><li>职业道德与法律法规有什么区别？</li><li>“预防为主，防消结合”属于方针还是原则？</li><li>为什么不能把“控制器安静了”当成“故障排除了”？</li><li>发现长期屏蔽时，为什么必须记录影响范围和临时措施？</li></ol><blockquote><p>参考：<a href="https://xfhyjd.119.gov.cn/zwossread/open1File/FirefightingSkillsAssessmentSystem/2025-11-13/4f0f6d863cf843228b5ce52030b59bb7/16193156145476990d82b-cb9d-43a7-a5f0-522abe3d1f8c%E5%9B%BD%E5%AE%B6%E8%81%8C%E4%B8%9A%E6%8A%80%E8%83%BD%E6%A0%87%E5%87%86%E2%80%94%E2%80%94%E6%B6%88%E9%98%B2%E8%AE%BE%E6%96%BD%E6%93%8D%E4%BD%9C%E5%91%98.pdf" target="_blank" rel="noreferrer">《消防设施操作员国家职业技能标准（2019年版）》</a> 2.1 职业道德；标准批准发布依据见<a href="/sources">权威依据</a>。</p></blockquote>',31)])])}const u=a(o,[["render",l]]);export{p as __pageData,u as default};
